INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5181055, 752262, 94235, '<td valign="top">Great capture.</td>', 'Great capture.', '2009-01-08 19:02:01.000000', NULL, 1),
(5181058, 752892, 94235, '<td valign="top">Good spin on the challenge and well photographed.</td>', 'Good spin on the challenge and well photographed.', '2009-01-08 19:02:48.000000', NULL, 1),
(5181061, 753879, 94235, '<td valign="top">Would have liked to see the number more in focus rather than the edge of the glass. Nice shot, and concept all the same.</td>', 'Would have liked to see the number more in focus rather than the edge of the glass. Nice shot, and concept all the same.', '2009-01-08 19:05:47.000000', NULL, 1),
(5181064, 753499, 94235, '<td valign="top">Good capture. Certainly not the fishes day!</td>', 'Good capture. Certainly not the fishes day!', '2009-01-08 19:06:44.000000', NULL, 1),
(5181066, 752554, 94235, '<td valign="top">Love the caption. Well shot.</td>', 'Love the caption. Well shot.', '2009-01-08 19:07:19.000000', NULL, 1),
(5181067, 753820, 94235, '<td valign="top">Nice capture.</td>', 'Nice capture.', '2009-01-08 19:07:40.000000', NULL, 1),
(5181069, 753573, 94235, '<td valign="top">Eerie setting. Well shot and framed.</td>', 'Eerie setting. Well shot and framed.', '2009-01-08 19:08:31.000000', NULL, 1),
(5181157, 753557, 101968, '<td valign="top">A technically beautiful photograph.</td>', 'A technically beautiful photograph.', '2009-01-08 20:27:36.000000', NULL, 1),
(5181160, 753882, 101968, '<td valign="top">13 is definitely unlucky, but technically this shot leaves a bit to be desired. Tighter focus and better lighting would have gone a long way to improve this.</td>', '13 is definitely unlucky, but technically this shot leaves a bit to be desired. Tighter focus and better lighting would have gone a long way to improve this.', '2009-01-08 20:29:14.000000', NULL, 1),
(5181162, 753598, 101968, '<td valign="top">A very good photo. I struggle to see the connection to "Unlucky", however.</td>', 'A very good photo. I struggle to see the connection to "Unlucky", however.', '2009-01-08 20:30:56.000000', NULL, 1),
(5181165, 751731, 101968, '<td valign="top">A nice photo. It definitely meets the challenge.</td>', 'A nice photo. It definitely meets the challenge.', '2009-01-08 20:32:40.000000', NULL, 1),
(5181170, 753316, 101968, '<td valign="top">I wonder how many people here actually train BJJ? I''ve shot a few tournaments and the shots people seem to like the best are certainly expressions like this, but I find people respond better when you get a whole lot closer.  You have preserved the context quite well, tho.</td>', 'I wonder how many people here actually train BJJ? I''ve shot a few tournaments and the shots people seem to like the best are certainly expressions like this, but I find people respond better when you get a whole lot closer.  You have preserved the context quite well, tho.', '2009-01-08 20:35:06.000000', NULL, 1),
(5181177, 751903, 101968, '<td valign="top">I''m not really feeling this one. The lighting is overly harsh, the pose seems forced and his fist is obscuring the subject. I''m not sure I see a connection to "Unlucky", either.</td>', 'I''m not really feeling this one. The lighting is overly harsh, the pose seems forced and his fist is obscuring the subject. I''m not sure I see a connection to "Unlucky", either.', '2009-01-08 20:36:32.000000', NULL, 1),
(5181178, 752979, 101968, '<td valign="top">A cute dog portrait, but "unlucky"?</td>', 'A cute dog portrait, but "unlucky"?', '2009-01-08 20:37:19.000000', NULL, 1),
(5181185, 753500, 101968, '<td valign="top">I''m not feeling the connection to "Unlucky".</td>', 'I''m not feeling the connection to "Unlucky".', '2009-01-08 20:40:03.000000', NULL, 1),
(5181187, 753802, 101968, '<td valign="top">I''m not feeling the connection to "Unlucky".</td>', 'I''m not feeling the connection to "Unlucky".', '2009-01-08 20:40:30.000000', NULL, 1),
(5181189, 753815, 101968, '<td valign="top">I''m not feeling the connection to "Unlucky".</td>', 'I''m not feeling the connection to "Unlucky".', '2009-01-08 20:40:52.000000', NULL, 1),
(5181190, 753136, 101968, '<td valign="top">I''m not feeling the connection to "Unlucky".</td>', 'I''m not feeling the connection to "Unlucky".', '2009-01-08 20:40:58.000000', NULL, 1),
(5181393, 753079, 58452, '<td valign="top">Photographing interesting road kill??? In this case you may be what you photograph. Humorous story.</td>', 'Photographing interesting road kill??? In this case you may be what you photograph. Humorous story.', '2009-01-08 22:06:09.000000', NULL, 1),
(5181400, 753864, 58452, '<td valign="top">I''m caused to wonder if WhiteRook has taken up a different hobby....</td>', 'I''m caused to wonder if WhiteRook has taken up a different hobby....', '2009-01-08 22:09:56.000000', NULL, 1),
(5181652, 753393, 99981, '<td valign="top">Hahahah! So creative!!</td>', 'Hahahah! So creative!!', '2009-01-09 01:00:09.000000', NULL, 1),
(5181653, 753281, 90952, '<td valign="top">I hate those dang things. When I lived in Australia, it seemed I couldn''t go outside without getting attacked by one.</td>', 'I hate those dang things. When I lived in Australia, it seemed I couldn''t go outside without getting attacked by one.', '2009-01-09 01:05:52.000000', NULL, 1),
(5181976, 753879, 85950, '<td valign="top">good choices for the symbols, but...</td>', 'good choices for the symbols, but...', '2009-01-09 10:16:19.000000', NULL, 1),
(5181978, 752382, 85950, '<td valign="top">:))</td>', ':))', '2009-01-09 10:18:15.000000', NULL, 1),
(5181984, 753875, 100727, '<td valign="top">I love the colour and tone.  Please share with us the editing steps.  Thank you.</td>', 'I love the colour and tone.  Please share with us the editing steps.  Thank you.', '2009-01-09 10:27:55.000000', NULL, 1),
(5181989, 752479, 100727, '<td valign="top">I like the idea.  I laughed when I saw the photo.  I love the expression on the faces.  However, I find the right side a bit too "noisy" (the bowl with something in it, and then there''s something behind the bowl).  It''s a nice shot nonetheless :)</td>', 'I like the idea.  I laughed when I saw the photo.  I love the expression on the faces.  However, I find the right side a bit too "noisy" (the bowl with something in it, and then there''s something behind the bowl).  It''s a nice shot nonetheless :)', '2009-01-09 10:32:25.000000', NULL, 1),
(5181993, 753557, 100727, '<td valign="top">I like the story!  8 replacing 13!  Very cleverly thought out.  Nice!  I viewed this photo a few times before deciding on the scale.  When the story came to me, then the scale went up!  10!</td>', 'I like the story!  8 replacing 13!  Very cleverly thought out.  Nice!  I viewed this photo a few times before deciding on the scale.  When the story came to me, then the scale went up!  10!', '2009-01-09 10:36:23.000000', NULL, 1),
(5182009, 753700, 100727, '<td valign="top">It''s a very interesting photo, however, it doesn''t tell the story too well.  I expect the orang utan to be inside a steel cage because your photo title is "Captured".  I do like the exposure and the mood of the creature.  Well done.</td>', 'It''s a very interesting photo, however, it doesn''t tell the story too well.  I expect the orang utan to be inside a steel cage because your photo title is "Captured".  I do like the exposure and the mood of the creature.  Well done.', '2009-01-09 10:49:50.000000', NULL, 1),
(5182010, 753200, 100727, '<td valign="top">.</td>', '.', '2009-01-09 10:50:12.000000', NULL, 1),
(5182161, 753775, 76585, '<td valign="top">I don''t get the title but I like the shot.</td>', 'I don''t get the title but I like the shot.', '2009-01-09 13:21:17.000000', NULL, 1),
(5182221, 753449, 61961, '<td valign="top">Good concept and you''ve conveyed the theme well.  I''m sure you''ll get faulted for the softness/blur, however.</td>', 'Good concept and you''ve conveyed the theme well.  I''m sure you''ll get faulted for the softness/blur, however.', '2009-01-09 13:54:31.000000', NULL, 1),
(5182304, 753252, 61961, '<td valign="top">Haha!  Well-executed.  I guess she "unluckily" hired a poor speller.</td>', 'Haha!  Well-executed.  I guess she "unluckily" hired a poor speller.', '2009-01-09 15:02:14.000000', NULL, 1),
(5182310, 753557, 61961, '<td valign="top">I like the concept, good execution though the red is a bit oversaturated looking.</td>', 'I like the concept, good execution though the red is a bit oversaturated looking.', '2009-01-09 15:06:15.000000', NULL, 1),
(5182512, 753374, 58452, '<td valign="top">Hahahaha, the funniest one yet! I like the composition and simplicity you''ve achieved. Nice frame, and I''m a big believer that less is more when it comes to frames. Congrats.</td>', 'Hahahaha, the funniest one yet! I like the composition and simplicity you''ve achieved. Nice frame, and I''m a big believer that less is more when it comes to frames. Congrats.', '2009-01-09 18:12:04.000000', NULL, 1),
(5182515, 752979, 58452, '<td valign="top">So sad.  LOL Exposure on the right shoulder is a bit hot and the bit of bright lamp above the head distracts just a bit. Maybe if the flash/light had been from the right the dogs'' eyes would be more distinct. Getting detail in a dogs eyes at night can be tough.</td>', 'So sad.  LOL Exposure on the right shoulder is a bit hot and the bit of bright lamp above the head distracts just a bit. Maybe if the flash/light had been from the right the dogs'' eyes would be more distinct. Getting detail in a dogs eyes at night can be tough.', '2009-01-09 18:16:37.000000', NULL, 1),
(5182516, 753875, 58452, '<td valign="top">Wow! Another one! Funny.  Til it happens to you! And just a shred!!! Nice lighting and a true representation of a night time horror!</td>', 'Wow! Another one! Funny.  Til it happens to you! And just a shred!!! Nice lighting and a true representation of a night time horror!', '2009-01-09 18:19:11.000000', NULL, 1),
(5182518, 753698, 102428, '<td valign="top">nice picture interesting twist</td>', 'nice picture interesting twist', '2009-01-09 18:19:53.000000', NULL, 1),
(5182521, 753200, 58452, '<td valign="top">Nice concept. Maybe a little less busy background would help simplify the image. The sharp shadows help complete the frame around the dog, but also tend to lead my eyes out of the frame for some reason.</td>', 'Nice concept. Maybe a little less busy background would help simplify the image. The sharp shadows help complete the frame around the dog, but also tend to lead my eyes out of the frame for some reason.', '2009-01-09 18:23:15.000000', NULL, 1),
(5182522, 752191, 16230, '<td valign="top">And how lucky is that when you need a shot for an "Unlucky" challenge? :D<br/> <br/>This is my nomination for 1st place. Congrats on such an unlucky shot!</td>', 'And how lucky is that when you need a shot for an "Unlucky" challenge? :D This is my nomination for 1st place. Congrats on such an unlucky shot!', '2009-01-09 18:24:17.000000', NULL, 1),
(5182526, 753557, 16230, '<td valign="top">This should do very well. Congrats!</td>', 'This should do very well. Congrats!', '2009-01-09 18:26:19.000000', NULL, 1),
(5182527, 753621, 58452, '<td valign="top">Puns a plenty in this challenge! I''d crop out the left a bit to eliminate the black background. The end of the pencil and front of the frame don''t seem to be perfectly in focus. Or it could be slight motion blur on a long shutter time.</td>', 'Puns a plenty in this challenge! I''d crop out the left a bit to eliminate the black background. The end of the pencil and front of the frame don''t seem to be perfectly in focus. Or it could be slight motion blur on a long shutter time.', '2009-01-09 18:27:55.000000', NULL, 1),
(5182528, 752310, 58452, '<td valign="top">Wow, RED FRAME!!!!! It stands out in front and detracts a bit from the image. Otherwise an interesting portrait. Maybe a bit better with some off camera flash.</td>', 'Wow, RED FRAME!!!!! It stands out in front and detracts a bit from the image. Otherwise an interesting portrait. Maybe a bit better with some off camera flash.', '2009-01-09 18:31:19.000000', NULL, 1),
(5182531, 753340, 58452, '<td valign="top">A popular theme in this challenge. I''d prefer a background that was pure and more of a color contrast to the clover and hand. The pose of the hand appears somewhat awkward.</td>', 'A popular theme in this challenge. I''d prefer a background that was pure and more of a color contrast to the clover and hand. The pose of the hand appears somewhat awkward.', '2009-01-09 18:33:44.000000', NULL, 1),
(5182535, 752191, 58452, '<td valign="top">Heheheh, isn''t it always that way when you travel! Nice sharp, colorful composition.  While a nice contrast to the red bridge and bldg, I''d have composed with a lot less of the green in the foreground, especially to get rid of the little triangle of dirt in the bottom left.</td>', 'Heheheh, isn''t it always that way when you travel! Nice sharp, colorful composition.  While a nice contrast to the red bridge and bldg, I''d have composed with a lot less of the green in the foreground, especially to get rid of the little triangle of dirt in the bottom left.', '2009-01-09 18:36:13.000000', NULL, 1),
(5182550, 753393, 58452, '<td valign="top">Exposure a touch hot for me on the toe tag and I''d have composed to eliminate the slight line in the bottom right of the frame. Otherwise I love it! With all the self-proclaimed third party accolades in the forums lately this is a perfect fit!!</td>', 'Exposure a touch hot for me on the toe tag and I''d have composed to eliminate the slight line in the bottom right of the frame. Otherwise I love it! With all the self-proclaimed third party accolades in the forums lately this is a perfect fit!!', '2009-01-09 18:43:37.000000', NULL, 1),
(5182555, 751903, 58452, '<td valign="top">A nice composition that suffers from horrible lighting. Moving the flash off camera would have helped a bunch. Backgrounds a bit busy too.</td>', 'A nice composition that suffers from horrible lighting. Moving the flash off camera would have helped a bunch. Backgrounds a bit busy too.', '2009-01-09 18:45:47.000000', NULL, 1),
(5182560, 753558, 58452, '<td valign="top">As  he slipped over the edge both hands reached for the sky hook that wasn''t there!!! Nice composition, although it doesn''t look like a landing yet.</td>', 'As  he slipped over the edge both hands reached for the sky hook that wasn''t there!!! Nice composition, although it doesn''t look like a landing yet.', '2009-01-09 18:48:49.000000', NULL, 1),
(5182562, 753619, 58452, '<td valign="top">Nice perspective shot. Keeps my eyes going from front to back and back to the subject again.</td>', 'Nice perspective shot. Keeps my eyes going from front to back and back to the subject again.', '2009-01-09 18:51:49.000000', NULL, 1),
(5182569, 752981, 58452, '<td valign="top">Nice composition and I love the shadow lines across the frame. Your images is very small, you do know that 720x pixels per side are allowed? Use every bit of screen real estate to show off your work!</td>', 'Nice composition and I love the shadow lines across the frame. Your images is very small, you do know that 720x pixels per side are allowed? Use every bit of screen real estate to show off your work!', '2009-01-09 18:55:03.000000', NULL, 1),
(5182574, 753713, 58452, '<td valign="top">Man, this was a popular idea in the challenge. Nice simple composition but somehow a little plain vanilla compared to the others. Maybe some edgy lighting could have helped.</td>', 'Man, this was a popular idea in the challenge. Nice simple composition but somehow a little plain vanilla compared to the others. Maybe some edgy lighting could have helped.', '2009-01-09 18:59:52.000000', NULL, 1),
(5182580, 753820, 58452, '<td valign="top">Hey! I had one of those in my scrambled eggs this morning! Nice composition and lighting but I''m not in love with the frame.</td>', 'Hey! I had one of those in my scrambled eggs this morning! Nice composition and lighting but I''m not in love with the frame.', '2009-01-09 19:02:08.000000', NULL, 1),
(5182585, 753598, 58452, '<td valign="top">Contrast! Everywhere. He only has his shadow, whilst everyone else is paired up. Nice technique to simplify while staying within the basic ruleset.</td>', 'Contrast! Everywhere. He only has his shadow, whilst everyone else is paired up. Nice technique to simplify while staying within the basic ruleset.', '2009-01-09 19:05:32.000000', NULL, 1),
(5182587, 752879, 58452, '<td valign="top">Nice sharp concept in your composition. Wish you could have eliminated the slight shadow on the background under the hand and pocket.  But that''s just a nit pik.</td>', 'Nice sharp concept in your composition. Wish you could have eliminated the slight shadow on the background under the hand and pocket.  But that''s just a nit pik.', '2009-01-09 19:07:06.000000', NULL, 1),
(5182592, 752892, 58452, '<td valign="top">I dialed that number and all I got was a Nigerian Western Union office!  Nice depth of field and leading lines.</td>', 'I dialed that number and all I got was a Nigerian Western Union office!  Nice depth of field and leading lines.', '2009-01-09 19:09:39.000000', NULL, 1),
(5182593, 753216, 58452, '<td valign="top">Interesting composition. I wonder if you''d zoomed in, either with lens or feet, and eliminated a lot of the "dead" space in the foreground.....</td>', 'Interesting composition. I wonder if you''d zoomed in, either with lens or feet, and eliminated a lot of the "dead" space in the foreground.....', '2009-01-09 19:13:30.000000', NULL, 1),
(5182596, 752382, 58452, '<td valign="top">Another one!!!! Maybe the current salmonella outbreak has pushed us to this theme!  heheh<br/>Simple composition, to the point with pretty good lighting.</td>', 'Another one!!!! Maybe the current salmonella outbreak has pushed us to this theme!  hehehSimple composition, to the point with pretty good lighting.', '2009-01-09 19:17:04.000000', NULL, 1),
(5182631, 753252, 102024, '<td valign="top">Yeah, that would suck a LOT</td>', 'Yeah, that would suck a LOT', '2009-01-09 19:52:39.000000', NULL, 1),
(5182633, 753864, 102024, '<td valign="top">Unfortunately, I''m not familiar with this game...</td>', 'Unfortunately, I''m not familiar with this game...', '2009-01-09 19:53:48.000000', NULL, 1),
(5182992, 752554, 58452, '<td valign="top">Interesting composition. All the lines even line up. LOL  You''re dedicating a lot of space to frame and remember you can go to 720 pixels. The bigger your image the easier it is to see!</td>', 'Interesting composition. All the lines even line up. LOL  You''re dedicating a lot of space to frame and remember you can go to 720 pixels. The bigger your image the easier it is to see!', '2009-01-10 03:06:09.000000', NULL, 1),
(5182993, 753658, 58452, '<td valign="top">Funny expression! Lighting on the sign and hand far too bright. Maybe some off camera flash could have helped separate the subject from the background and balanced the exposure.</td>', 'Funny expression! Lighting on the sign and hand far too bright. Maybe some off camera flash could have helped separate the subject from the background and balanced the exposure.', '2009-01-10 03:06:13.000000', NULL, 1),
(5182994, 753252, 58452, '<td valign="top">Ahhh, that angle of approach! heheheh Maybe moving the softlight on the left around could reduce some of the glare on her left shoulder. Nice tats.</td>', 'Ahhh, that angle of approach! heheheh Maybe moving the softlight on the left around could reduce some of the glare on her left shoulder. Nice tats.', '2009-01-10 03:06:17.000000', NULL, 1),
(5183166, 752460, 93756, '<td valign="top">Good attention to detail: sign on the fridge is not too obvious, etc. Good idea for the challenge. Would have more zing if his face was sharpened and his hand was more in focus.</td>', 'Good attention to detail: sign on the fridge is not too obvious, etc. Good idea for the challenge. Would have more zing if his face was sharpened and his hand was more in focus.', '2009-01-10 09:11:11.000000', NULL, 1),
(5183168, 753658, 93756, '<td valign="top">Extra point for getting me to laugh!</td>', 'Extra point for getting me to laugh!', '2009-01-10 09:12:28.000000', NULL, 1),
(5183170, 752981, 93756, '<td valign="top">Really beautiful photo.</td>', 'Really beautiful photo.', '2009-01-10 09:13:08.000000', NULL, 1),
(5183358, 753562, 99140, '<td valign="top">I LOVE bullriding shots (have a few myself).  The capture itself in the timing is impecible just wish it was a closer shot and crisper to see more detail in the riders face.  Just my 2 cents.</td>', 'I LOVE bullriding shots (have a few myself).  The capture itself in the timing is impecible just wish it was a closer shot and crisper to see more detail in the riders face.  Just my 2 cents.', '2009-01-10 12:13:36.000000', NULL, 1),
(5183361, 753252, 99140, '<td valign="top">That is hilarious!  Great concept!</td>', 'That is hilarious!  Great concept!', '2009-01-10 12:15:10.000000', NULL, 1),
(5183375, 752981, 83080, '<td valign="top">I like the tree/shadow lines.  Nice geometry in this shot.</td>', 'I like the tree/shadow lines.  Nice geometry in this shot.', '2009-01-10 12:24:04.000000', NULL, 1),
(5183480, 753802, 30791, '<td valign="top">omg thats bloody cold, i dont even know if ive ever been exposed to something that cold. geeeze</td>', 'omg thats bloody cold, i dont even know if ive ever been exposed to something that cold. geeeze', '2009-01-10 13:46:09.000000', NULL, 1),
(5183482, 752320, 30791, '<td valign="top">BSOD blows, and a CRT monitor? really?</td>', 'BSOD blows, and a CRT monitor? really?', '2009-01-10 13:48:14.000000', NULL, 1),
(5183515, 753733, 43442, '<td valign="top">Would have scored higher if , some of the right side was cropped.  This would take away some of the bright ( Bald ) sky.  The bright Sky and the lines on the road, lead ones eyes away from the strong image of the Man.</td>', 'Would have scored higher if , some of the right side was cropped.  This would take away some of the bright ( Bald ) sky.  The bright Sky and the lines on the road, lead ones eyes away from the strong image of the Man.', '2009-01-10 14:13:06.000000', NULL, 1),
(5183569, 753528, 102315, '<td valign="top">Such a sad picture</td>', 'Such a sad picture', '2009-01-10 15:02:23.000000', NULL, 1),
(5183570, 752979, 102315, '<td valign="top">Beautiful dog</td>', 'Beautiful dog', '2009-01-10 15:02:40.000000', NULL, 1),
(5183572, 752892, 102315, '<td valign="top">WOW what a phone number. Great idea for the unlucky challenge!</td>', 'WOW what a phone number. Great idea for the unlucky challenge!', '2009-01-10 15:03:30.000000', NULL, 1),
(5183574, 753829, 102315, '<td valign="top">I love this picture. Great color and great positioning.</td>', 'I love this picture. Great color and great positioning.', '2009-01-10 15:04:36.000000', NULL, 1),
(5183575, 753393, 102315, '<td valign="top">Great concept</td>', 'Great concept', '2009-01-10 15:05:41.000000', NULL, 1),
(5183585, 753281, 102315, '<td valign="top">Beautiful shot of a hideous bird!</td>', 'Beautiful shot of a hideous bird!', '2009-01-10 15:12:55.000000', NULL, 1),
(5183619, 753374, 102088, '<td valign="top">Funny how this has been a popular theme I guess it''s happened to us all at some time!!nicely lit</td>', 'Funny how this has been a popular theme I guess it''s happened to us all at some time!!nicely lit', '2009-01-10 15:36:22.000000', NULL, 1),
