(5183626, 753777, 102088, '<td valign="top">powerful stuff!! and very thought provoking</td>', 'powerful stuff!! and very thought provoking', '2009-01-10 15:40:44.000000', NULL, 1),
(5183629, 753777, 25522, '<td valign="top">10 From me.  I love the sepia, the juxtaposition of the stone against the palmed sky, and the clarity of the engraving.  Great job!</td>', '10 From me.  I love the sepia, the juxtaposition of the stone against the palmed sky, and the clarity of the engraving.  Great job!', '2009-01-10 15:42:03.000000', NULL, 1),
(5183632, 753547, 102088, '<td valign="top">great colour</td>', 'great colour', '2009-01-10 15:43:37.000000', NULL, 1),
